import{_ as t,o as a,c as o,a0 as n}from"./chunks/framework.DYS8d9tm.js";const h=JSON.parse('{"title":"📖 WealthFam — How To Use Guide","description":"","frontmatter":{},"headers":[],"relativePath":"user/usage_guide.md","filePath":"user/usage_guide.md"}'),i={name:"user/usage_guide.md"};function r(s,e,l,d,c,g){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="📖-wealthfam-—-how-to-use-guide" tabindex="-1">📖 WealthFam — How To Use Guide <a class="header-anchor" href="#📖-wealthfam-—-how-to-use-guide" aria-label="Permalink to &quot;📖 WealthFam — How To Use Guide&quot;">​</a></h1><blockquote><p>A comprehensive operating manual for both the <strong>Web Dashboard</strong> (VueJS) and the <strong>Mobile App</strong> (Flutter).</p></blockquote><hr><h2 id="🚀-1-getting-started" tabindex="-1">🚀 1. Getting Started <a class="header-anchor" href="#🚀-1-getting-started" aria-label="Permalink to &quot;🚀 1. Getting Started&quot;">​</a></h2><h3 id="first-time-registration-web" tabindex="-1">First-Time Registration (Web) <a class="header-anchor" href="#first-time-registration-web" aria-label="Permalink to &quot;First-Time Registration (Web)&quot;">​</a></h3><ol><li>Navigate to the WealthFam URL and click <strong>Register</strong>.</li><li>Enter a <strong>Family Name</strong> (this creates your <strong>Tenant</strong> — the shared family workspace).</li><li>Fill in your email, password, and profile details (full name, avatar emoji).</li><li>You are now the <strong>OWNER</strong> of the tenant with full administrative rights.</li></ol><h3 id="mobile-app-setup" tabindex="-1">Mobile App Setup <a class="header-anchor" href="#mobile-app-setup" aria-label="Permalink to &quot;Mobile App Setup&quot;">​</a></h3><ol><li>Install the APK on your Android device.</li><li>On first launch, go to <strong>Settings → Server Configuration</strong> and enter your backend URL.</li><li>Login with the same credentials used on the web.</li><li>The app will generate a unique <strong>Device ID</strong>. If required, the Tenant Admin must approve this device from <strong>Web → Settings → Devices</strong> before sync can begin.</li></ol><h3 id="adding-family-members" tabindex="-1">Adding Family Members <a class="header-anchor" href="#adding-family-members" aria-label="Permalink to &quot;Adding Family Members&quot;">​</a></h3><ol><li>Go to <strong>Settings → Family</strong> on the web dashboard.</li><li>Click <strong>Add Member</strong> and provide their email and assign a role: <ul><li><strong>Adult</strong>: Full financial access.</li><li><strong>Child</strong>: Restricted to personal goals only.</li><li><strong>Guest</strong>: Read-only.</li></ul></li><li>The new member can then register with that email and will automatically join your family tenant.</li></ol><hr><h2 id="📱-2-sms-transaction-sync-mobile-—-android" tabindex="-1">📱 2. SMS Transaction Sync (Mobile — Android) <a class="header-anchor" href="#📱-2-sms-transaction-sync-mobile-—-android" aria-label="Permalink to &quot;📱 2. SMS Transaction Sync (Mobile — Android)&quot;">​</a></h2><h3 id="initial-permission-setup" tabindex="-1">Initial Permission Setup <a class="header-anchor" href="#initial-permission-setup" aria-label="Permalink to &quot;Initial Permission Setup&quot;">​</a></h3><ol><li>Open the mobile app. On first use, it will request <strong>SMS</strong> and <strong>Location</strong> permissions.</li><li><strong>SMS Permission</strong>: Required for reading bank transaction messages. Grant &quot;Allow&quot;.</li><li><strong>Location Permission</strong>: Set to <strong>&quot;Always Allow&quot;</strong> for highest Precision precision. Without this, GPS coordinates will be missing or use last-known position.</li></ol><h3 id="how-sms-sync-works" tabindex="-1">How SMS Sync Works <a class="header-anchor" href="#how-sms-sync-works" aria-label="Permalink to &quot;How SMS Sync Works&quot;">​</a></h3><ul><li>Once permissions are granted, the app listens for incoming SMS <strong>in real-time</strong>, both in foreground and background.</li><li>Each SMS is locally hashed (SHA-256) to prevent duplicates, then sent to the backend with GPS coordinates.</li><li>The backend&#39;s AI parser extracts the transaction details (amount, date, merchant, account) and either auto-confirms or places it in the <strong>Triage Queue</strong> for review.</li></ul><h3 id="enabling-the-foreground-service-recommended" tabindex="-1">Enabling the Foreground Service (Recommended) <a class="header-anchor" href="#enabling-the-foreground-service-recommended" aria-label="Permalink to &quot;Enabling the Foreground Service (Recommended)&quot;">​</a></h3><ol><li>Go to <strong>Mobile App → SMS Management → Toggle &quot;Foreground Service&quot;</strong>.</li><li>This keeps a persistent notification showing <code>Today: ₹X • Month: ₹Y</code>.</li><li>Benefits: More reliable background operation, real-time spending awareness, and poll-based alert delivery when WebSocket is disconnected.</li></ol><h3 id="manual-sync-catch-up" tabindex="-1">Manual Sync &amp; Catch-Up <a class="header-anchor" href="#manual-sync-catch-up" aria-label="Permalink to &quot;Manual Sync &amp; Catch-Up&quot;">​</a></h3><ul><li>Tap <strong>&quot;Sync Now&quot;</strong> on the SMS Management screen to: <ol><li>Retry all queued offline messages.</li><li>Scan the device inbox for the last <strong>72 hours</strong> of unprocessed messages.</li></ol></li><li>Use <strong>&quot;Push All Unsynced&quot;</strong> for a complete inbox scan (all time).</li></ul><h3 id="checking-sync-status" tabindex="-1">Checking Sync Status <a class="header-anchor" href="#checking-sync-status" aria-label="Permalink to &quot;Checking Sync Status&quot;">​</a></h3><ul><li>The SMS Management screen shows: <ul><li><strong>Last Sync Time</strong>: When the last successful sync occurred.</li><li><strong>Messages Synced Today</strong>: Counter resets daily.</li><li><strong>Queue Count</strong>: Number of messages waiting for retry.</li><li><strong>Debug Logs</strong>: Raw payloads sent to the backend (enable in settings).</li></ul></li></ul><hr><h2 id="🏦-3-account-setup" tabindex="-1">🏦 3. Account Setup <a class="header-anchor" href="#🏦-3-account-setup" aria-label="Permalink to &quot;🏦 3. Account Setup&quot;">​</a></h2><h3 id="adding-accounts-web" tabindex="-1">Adding Accounts (Web) <a class="header-anchor" href="#adding-accounts-web" aria-label="Permalink to &quot;Adding Accounts (Web)&quot;">​</a></h3><ol><li>Go to <strong>Settings → Accounts</strong> and click <strong>Add Account</strong>.</li><li>Choose the account type: <ul><li><strong>Bank</strong>: Savings/Checking (enter an account mask like <code>XX1234</code> for SMS matching).</li><li><strong>Credit Card</strong>: Enter credit limit, billing day, and due day for cycle intelligence.</li><li><strong>Wallet</strong>: Digital wallets (Paytm, PhonePe, etc.).</li><li><strong>Loan</strong>: Will prompt for loan details (see Loans section).</li></ul></li><li>The <strong>Account Mask</strong> is critical — it&#39;s the last 4+ digits of your account number that appears in bank SMS messages (e.g., <code>*1234</code>). This is how WealthFam knows which account an SMS transaction belongs to.</li></ol><h3 id="credit-card-intelligence" tabindex="-1">Credit Card Intelligence <a class="header-anchor" href="#credit-card-intelligence" aria-label="Permalink to &quot;Credit Card Intelligence&quot;">​</a></h3><p>Once you set the <strong>Billing Day</strong> and <strong>Due Day</strong> for a credit card, WealthFam performs Precision cycle analysis:</p><ul><li><strong>Statement Balance</strong>: Automatically calculated even if the bank doesn&#39;t report it (<code>Current Balance - Unbilled Purchases - Payments Since Statement</code>).</li><li><strong>Unbilled Spend</strong>: Live tracking of new purchases in the current cycle that haven&#39;t shifted to a statement yet.</li><li><strong>Utilization Tracking</strong>: Visual indicators and alerts for high debt-to-limit ratios.</li><li><strong>Next Due Date</strong>: Real-time ticker showing days remaining until payment is required.</li><li><strong>Credit Outlook</strong>: A dedicated dashboard panel for aggregated debt health across all cards.</li></ul><hr><h2 id="📄-4-bulk-statement-ingestion-web" tabindex="-1">📄 4. Bulk Statement Ingestion (Web) <a class="header-anchor" href="#📄-4-bulk-statement-ingestion-web" aria-label="Permalink to &quot;📄 4. Bulk Statement Ingestion (Web)&quot;">​</a></h2><p>For banks or cards not yet supported by real-time SMS sync, or to backfill historical data, use the <strong>Bulk Ingestion</strong> feature.</p><h3 id="uploading-a-statement" tabindex="-1">Uploading a Statement <a class="header-anchor" href="#uploading-a-statement" aria-label="Permalink to &quot;Uploading a Statement&quot;">​</a></h3><ol><li>Navigate to <strong>Banking → Statements</strong> on the web dashboard.</li><li>Click <strong>Upload Statement</strong>.</li><li>Select your bank&#39;s PDF or CSV file.</li><li>If the PDF is encrypted, the system will attempt to auto-unlock it using common patterns (e.g., PAN + DOB). If it fails, you will be prompted for a <strong>Manual Password</strong>.</li></ol><h3 id="reconciliation-rule-generation" tabindex="-1">Reconciliation &amp; Rule Generation <a class="header-anchor" href="#reconciliation-rule-generation" aria-label="Permalink to &quot;Reconciliation &amp; Rule Generation&quot;">​</a></h3><ol><li>Once uploaded, the statement appears in the list. Click <strong>Reconcile</strong>.</li><li>A bulk ingestion dialog will appear showing all extracted transactions.</li><li><strong>Smart Classification</strong>: <ul><li>Transactions already matched by existing rules or AI will have a category pre-selected.</li><li>For new merchants, select a category from the tree-based dropdown.</li></ul></li><li><strong>Automated Rule Creation</strong>: <ul><li>Toggle <strong>&quot;Save Rule&quot;</strong> to automatically create a classification rule for that merchant.</li><li>The rule is generated based on the transaction&#39;s description, ensuring future statements are auto-categorized.</li></ul></li><li>Click <strong>Confirm Import</strong> to move all selected transactions into your ledger.</li></ol><h3 id="managing-statements-filter-edit-reprocess-delete" tabindex="-1">Managing Statements (Filter, Edit, Reprocess &amp; Delete) <a class="header-anchor" href="#managing-statements-filter-edit-reprocess-delete" aria-label="Permalink to &quot;Managing Statements (Filter, Edit, Reprocess &amp; Delete)&quot;">​</a></h3><ul><li><strong>Filter &amp; Search</strong>: Filter statements by status (<code>All</code>, <code>Parsed</code>, <code>Pending</code>, <code>Failed</code>), statement type, or search by filename. Toggle the <strong>Show Attended</strong> switch to view closed statements.</li><li><strong>Edit Statement Metadata</strong>: Click <strong>Edit</strong> on a statement to update its display <code>filename</code> (automatically synced with its linked Document Vault entry), <code>statement_type</code>, or linked account (re-linking an account automatically triggers reprocess/reconciliation for <code>FAILED</code> statements). Extracted statement line items remain read-only for audit integrity.</li><li><strong>Password Retry &amp; Partial Unlock</strong>: On locked (<code>PENDING</code>) or failed statements, click <strong>Unlock / Reprocess</strong> to supply a manual password. If unlocking succeeds and saves the decrypted PDF into the Vault even when downstream parsing still needs attention, WealthFam keeps the unlocked PDF accessible in Vault alongside the diagnostic status.</li><li><strong>Single &amp; Bulk Delete</strong>: Delete an individual statement or select multiple rows for <strong>Bulk Delete</strong>, with options to remove linked unreferenced Vault PDFs and create a sender ignore rule in one step.</li></ul><h3 id="statement-attendance-review-lifecycle" tabindex="-1">Statement Attendance &amp; Review Lifecycle <a class="header-anchor" href="#statement-attendance-review-lifecycle" aria-label="Permalink to &quot;Statement Attendance &amp; Review Lifecycle&quot;">​</a></h3><ul><li><strong>Mark Attended (<code>✓ Attended</code>)</strong>: When you have completed reviewing a statement, click <strong>Mark Attended</strong>. This moves the statement into the attended archive, clears the attention queue, and protects the statement from accidental modification (disabling checkboxes, edit, and reprocess actions).</li><li><strong>Import Status vs. Attended Status</strong>: Marking a statement as attended <strong>does not import un-imported transactions</strong>. <ul><li>Transactions previously imported into your portfolio or matched to your bank ledger display <strong><code>✓ Imported</code></strong> or <strong><code>✓ Matched</code></strong>.</li><li>Transactions that were skipped display neutral <strong><code>Unimported</code></strong> (CAS) or <strong><code>Unmatched</code></strong> (Bank) indicators.</li><li>If you close a statement with un-imported transactions remaining, an amber banner highlights: <code>Notice: Marked as Attended with N unreconciled transaction(s)</code>.</li></ul></li><li><strong>Reopening a Statement</strong>: If you need to import skipped transactions later, click <strong>Reopen</strong>. The statement immediately returns to review mode, unimported transactions switch back to <code>Ready</code>, and checkboxes re-enable.</li></ul><h3 id="mutual-fund-cas-statement-ingestion-portfolio-import" tabindex="-1">Mutual Fund CAS Statement Ingestion &amp; Portfolio Import <a class="header-anchor" href="#mutual-fund-cas-statement-ingestion-portfolio-import" aria-label="Permalink to &quot;Mutual Fund CAS Statement Ingestion &amp; Portfolio Import&quot;">​</a></h3><ul><li><strong>Automated Scheme &amp; Folio Mapping</strong>: CAS PDFs (CAMS, KFintech, CDSL, NSDL) and AMC SOAs (Nippon India, Quant, Groww) are automatically parsed via <code>casparser 1.x</code> (<code>pypdfium2</code> engine) and matched against the AMFI mutual fund catalogue.</li><li><strong>Duplicate Detection</strong>: The system checks extracted transactions against your existing investment orders. Transactions already present in your portfolio are badged as <strong><code>Duplicate</code></strong> and automatically excluded from import selection.</li><li><strong>Import to Portfolio</strong>: Click <strong>Import to Portfolio</strong> to ingest selected mutual fund transactions into your active portfolio holdings and orders. Holding balances and units recalculate automatically with zero manual entry.</li><li><strong>Reprocessing Dynamic Sync</strong>: If duplicate status changes after updating other accounts or holdings, click the <strong>Reprocess / Re-evaluate</strong> action to re-verify the PDF against your latest live ledger.</li></ul><h3 id="blocking-unwanted-statement-emails-statement-ignore-rules" tabindex="-1">Blocking Unwanted Statement Emails (Statement Ignore Rules) <a class="header-anchor" href="#blocking-unwanted-statement-emails-statement-ignore-rules" aria-label="Permalink to &quot;Blocking Unwanted Statement Emails (Statement Ignore Rules)&quot;">​</a></h3><ul><li>Click the 🚫 <strong>Ignore</strong> action on any unwanted promotional, margin, or non-statement PDF attachment to block future emails matching the <strong>Sender</strong>, <strong>Email Subject</strong>, or <strong>Filename Keyword</strong>, and optionally remove existing matching <code>PENDING</code>/<code>FAILED</code> statements while keeping <code>PARSED</code> statement history untouched.</li><li>Click <strong>Ignored Rules</strong> in <strong>Banking → Statements</strong> (or manage rules under <strong>Settings → Ingestions</strong>) to view, add, or remove <code>STATEMENT</code> ignore rules at any time.</li></ul><hr><h2 id="📧-5-email-sync-cams-bank-emails" tabindex="-1">📧 5. Email Sync (CAMS &amp; Bank Emails) <a class="header-anchor" href="#📧-5-email-sync-cams-bank-emails" aria-label="Permalink to &quot;📧 5. Email Sync (CAMS &amp; Bank Emails)&quot;">​</a></h2><h3 id="setting-up-email-sync" tabindex="-1">Setting Up Email Sync <a class="header-anchor" href="#setting-up-email-sync" aria-label="Permalink to &quot;Setting Up Email Sync&quot;">​</a></h3><ol><li>Go to <strong>Settings → Email Sync</strong> on the web dashboard.</li><li>Click <strong>Add Email Configuration</strong>.</li><li>Provide: <ul><li><strong>IMAP Server</strong>: <code>imap.gmail.com</code> for Gmail, <code>imap-mail.outlook.com</code> for Outlook.</li><li><strong>Email</strong>: Your email address.</li><li><strong>Password</strong>: For Gmail, use an <a href="https://support.google.com/accounts/answer/185833" target="_blank" rel="noreferrer">App Password</a> (not your regular password).</li><li><strong>Folder</strong>: Usually <code>INBOX</code>.</li></ul></li><li>Enable <strong>Auto-Sync</strong> to let the system check for new emails every 3 hours automatically.</li></ol><h3 id="manual-email-sync" tabindex="-1">Manual Email Sync <a class="header-anchor" href="#manual-email-sync" aria-label="Permalink to &quot;Manual Email Sync&quot;">​</a></h3><ul><li>On the Email Settings page, click <strong>Sync Now</strong> to trigger an immediate scan.</li><li>The sync will fetch unread (or all, depending on configuration) emails, filter out noise, and parse financial transactions.</li><li>Results appear in the <strong>Sync Logs</strong> section.</li></ul><h3 id="cas-sync-—-cams-kfintech-cdsl-nsdl-mutual-funds" tabindex="-1">CAS Sync — CAMS / KFintech / CDSL / NSDL (Mutual Funds) <a class="header-anchor" href="#cas-sync-—-cams-kfintech-cdsl-nsdl-mutual-funds" aria-label="Permalink to &quot;CAS Sync — CAMS / KFintech / CDSL / NSDL (Mutual Funds)&quot;">​</a></h3><ol><li>Ensure you have an email configuration set up.</li><li>Navigate to <strong>Mutual Funds → Settings</strong> (or the CAS Sync section).</li><li>If your CAS PDFs are password-protected, enter the standard password (usually your PAN + DOB).</li><li>Click <strong>Sync CAS</strong> — the system will: <ul><li>Scan for emails from <code>camsonline</code>, <code>eCAS@cdslstatement.com</code>, <code>cdslindia</code>, KFintech/NSDL senders, or with subject <code>&quot;Consolidated Account Statement&quot;</code>.</li><li>Download PDF attachments into the persistent Document Vault.</li><li>Automatically unlock, vault, and parse them.</li><li>Map extracted transactions to mutual fund schemes and update your holdings.</li></ul></li></ol><h3 id="automated-statement-fetching-bank-statements" tabindex="-1">Automated Statement Fetching (Bank Statements) <a class="header-anchor" href="#automated-statement-fetching-bank-statements" aria-label="Permalink to &quot;Automated Statement Fetching (Bank Statements)&quot;">​</a></h3><p>Beyond Mutual Funds, WealthFam can automatically monitor your inbox for bank and credit card statements.</p><ol><li>When <strong>Auto-Sync</strong> is enabled, the system scans for emails containing &quot;Statement&quot; or &quot;E-Statement&quot; from supported financial institutions.</li><li>Detected PDF attachments are automatically downloaded to the <strong>Vault</strong>.</li><li>If the statement&#39;s bank is recognized (e.g., HDFC, Swiggy HDFC), the system pre-processes the statement and places it in <strong>Banking → Statements</strong> for final reconciliation.</li><li><strong>Zero-Touch Ingestion</strong>: This turns the monthly statement routine into a simple &quot;Click to Reconcile&quot; action without ever downloading files to your computer.</li></ol><hr><h2 id="📊-6-using-the-dashboard" tabindex="-1">📊 6. Using the Dashboard <a class="header-anchor" href="#📊-6-using-the-dashboard" aria-label="Permalink to &quot;📊 6. Using the Dashboard&quot;">​</a></h2><h3 id="web-dashboard" tabindex="-1">Web Dashboard <a class="header-anchor" href="#web-dashboard" aria-label="Permalink to &quot;Web Dashboard&quot;">​</a></h3><p>The dashboard is your command center. It loads automatically after login:</p><table tabindex="0"><thead><tr><th>Card</th><th>What It Shows</th><th>Click To</th></tr></thead><tbody><tr><td><strong>Net Worth</strong></td><td>Total (Bank + Investments - Debt) with 30-day sparkline</td><td>Go to Dashboard</td></tr><tr><td><strong>Monthly Spending</strong></td><td>This month&#39;s spending vs. last month (same-day comparison)</td><td>Go to Transactions</td></tr><tr><td><strong>Mutual Funds</strong></td><td>Portfolio value, P&amp;L, XIRR %</td><td>Go to Mutual Funds</td></tr><tr><td><strong>Remaining Budget</strong></td><td>Budget left with % spent</td><td>Go to Budgets</td></tr></tbody></table><p>Below the top cards:</p><ul><li><strong>Wealth Compass</strong>: Comprehensive wealth overview visualization.</li><li><strong>AI Intelligence</strong>: 3 AI-generated insights (auto-refreshes every 24 hours, can force-refresh).</li><li><strong>Activity Pulse</strong>: Real-time family activity feed via WebSocket notifications.</li><li><strong>Recent Activity</strong>: Last 5 transactions with category icons and member attribution.</li><li><strong>Upcoming Bills</strong>: Next 30 days of recurring transactions.</li><li><strong>Credit Outlook</strong>: Per-card billing cycle intelligence.</li></ul><h3 id="mobile-dashboard" tabindex="-1">Mobile Dashboard <a class="header-anchor" href="#mobile-dashboard" aria-label="Permalink to &quot;Mobile Dashboard&quot;">​</a></h3><p>The mobile dashboard consolidates all data into a <strong>single API call</strong> for fast loading:</p><ul><li><strong>Today/Yesterday/Last Month Same Day</strong> comparison cards.</li><li><strong>Monthly Total</strong> with budget progress bar.</li><li><strong>Daily Spending Trend</strong> chart.</li><li><strong>Category Breakdown</strong> donut chart.</li><li><strong>Investment Summary</strong> (if applicable) with live XIRR.</li><li><strong>Recent Transactions</strong> with swipe-to-view.</li></ul><hr><h2 id="💳-7-managing-transactions" tabindex="-1">💳 7. Managing Transactions <a class="header-anchor" href="#💳-7-managing-transactions" aria-label="Permalink to &quot;💳 7. Managing Transactions&quot;">​</a></h2><h3 id="viewing-transactions-web" tabindex="-1">Viewing Transactions (Web) <a class="header-anchor" href="#viewing-transactions-web" aria-label="Permalink to &quot;Viewing Transactions (Web)&quot;">​</a></h3><ol><li>Navigate to <strong>Transactions</strong> from the sidebar.</li><li>Use the filter bar to narrow by: <ul><li><strong>Date Range</strong>: Custom start/end dates.</li><li><strong>Account</strong>: Filter by specific bank/card.</li><li><strong>Category</strong>: Filter by spending category.</li><li><strong>Type</strong>: Credit/Debit.</li></ul></li><li>Click any transaction to open the <strong>Transaction Modal</strong> for full details and editing.</li></ol><h3 id="editing-a-transaction" tabindex="-1">Editing a Transaction <a class="header-anchor" href="#editing-a-transaction" aria-label="Permalink to &quot;Editing a Transaction&quot;">​</a></h3><p>In the Transaction Modal, you can:</p><ul><li>Change <strong>Category</strong>, <strong>Description</strong>, and <strong>Recipient</strong>.</li><li>Assign to an <strong>Expense Group</strong> (e.g., &quot;Vacation&quot;).</li><li>Mark as <strong>Transfer</strong> (and link the destination account).</li><li>Link to a <strong>Loan</strong> (for EMI tracking).</li><li>Toggle <strong>Exclude from Reports</strong> (hides from budget calculations).</li><li>Attach <strong>Documents</strong> from the Vault.</li></ul><h3 id="transaction-triage-review-queue" tabindex="-1">Transaction Triage (Review Queue) <a class="header-anchor" href="#transaction-triage-review-queue" aria-label="Permalink to &quot;Transaction Triage (Review Queue)&quot;">​</a></h3><p>When the parser can&#39;t fully auto-categorize a transaction OR confidence is low:</p><ol><li>Navigate to <strong>Transactions → Triage</strong> tab.</li><li>Each pending transaction shows the parsed data alongside the raw SMS/email content.</li><li>You can: <ul><li><strong>Approve</strong>: Confirms the transaction as-is (or edit before confirming).</li><li><strong>Discard</strong>: Removes it from the queue.</li><li><strong>Bulk Approve</strong>: Select multiple and approve at once.</li></ul></li><li>Approved transactions move to the main <code>transactions</code> table.</li></ol><h3 id="adding-transactions-manually" tabindex="-1">Adding Transactions Manually <a class="header-anchor" href="#adding-transactions-manually" aria-label="Permalink to &quot;Adding Transactions Manually&quot;">​</a></h3><ul><li><strong>Web</strong>: Click the <strong>&quot;+&quot;</strong> button or use the import modal.</li><li><strong>Mobile</strong>: Go to the home screen and tap <strong>Add Transaction</strong> — fill in amount, date, description, category, and account.</li></ul><hr><h2 id="📈-8-mutual-funds-investments" tabindex="-1">📈 8. Mutual Funds &amp; Investments <a class="header-anchor" href="#📈-8-mutual-funds-investments" aria-label="Permalink to &quot;📈 8. Mutual Funds &amp; Investments&quot;">​</a></h2><h3 id="viewing-your-portfolio" tabindex="-1">Viewing Your Portfolio <a class="header-anchor" href="#viewing-your-portfolio" aria-label="Permalink to &quot;Viewing Your Portfolio&quot;">​</a></h3><ol><li>Click <strong>Mutual Funds</strong> in the sidebar (Web) or navigate to the funds tab (Mobile).</li><li>The overview shows all holdings grouped by scheme with: <ul><li>Current Value, Units, Average NAV, Last NAV.</li><li>Profit/Loss (absolute and percentage).</li><li>XIRR (annualized return).</li></ul></li></ol><h3 id="fund-details-transaction-management" tabindex="-1">Fund Details &amp; Transaction Management <a class="header-anchor" href="#fund-details-transaction-management" aria-label="Permalink to &quot;Fund Details &amp; Transaction Management&quot;">​</a></h3><p>Click any scheme to open the <strong>Deep-Dive Management Modal</strong>:</p><ul><li><strong>Consolidated History</strong>: View every historical BUY/SELL order with audited NAVs and unit counts.</li><li><strong>Surgical Corrections</strong>: Edit or soft-delete individual transactions directly from the history grid to correct data entry errors.</li><li><strong>Predictive &#39;What-If&#39; Analysis</strong>: Before deleting a transaction or a folio, the system provides a live projected impact—showing exactly how your Profit/Loss, Invested Value, and XIRR will change.</li><li><strong>Folio Removal</strong>: Quickly remove entire folios while maintaining a non-destructive audit trail (Soft-Delete).</li></ul><h3 id="performance-precision" tabindex="-1">Performance &amp; Precision <a class="header-anchor" href="#performance-precision" aria-label="Permalink to &quot;Performance &amp; Precision&quot;">​</a></h3><ul><li><strong>Absolute Accuracy</strong>: All portfolio calculations (Average Price, P&amp;L, Value) are performed using the <strong>Decimal precision standard</strong>, eliminating longitudinal rounding errors common in other apps.</li><li><strong>XIRR Engine</strong>: Annualized returns are calculated based on your actual verified cash flows, including buy/sell timings and current market valuations.</li></ul><h3 id="❓-troubleshooting-faq" tabindex="-1">❓ Troubleshooting &amp; FAQ <a class="header-anchor" href="#❓-troubleshooting-faq" aria-label="Permalink to &quot;❓ Troubleshooting &amp; FAQ&quot;">​</a></h3><ul><li><strong>&quot;I deleted a transaction but my portfolio value didn&#39;t change!&quot;</strong><ul><li><strong>Check Recalculation</strong>: The dashboard usually updates instantly, but complex portfolios may require a manual &quot;Recalculate Holdings&quot; from the settings to force a full cost-basis audit.</li></ul></li><li><strong>&quot;My Average Cost looks incorrect.&quot;</strong><ul><li><strong>Root Cause</strong>: Often caused by a missing historical buy order or a duplicate CAMS entry. Use the <strong>Deep-Dive historical grid</strong> to find the anomaly and correct the individual order&#39;s units/NAV.</li></ul></li><li><strong>&quot;I see a &#39;Not in Portfolio&#39; error after deleting a transaction.&quot;</strong><ul><li><strong>Recovery</strong>: WealthFam uses <strong>Identity-Stable In-Place Updates</strong>. If you delete the <em>last</em> transaction of a holding, the holding becomes empty and is removed from the active view. The internal ID is preserved, so if you add a new transaction later, your historical links (Goals) will reactivate automatically.</li></ul></li><li><strong>&quot;What does &#39;Soft-Delete&#39; mean for my data?&quot;</strong><ul><li><strong>Audit Trail</strong>: Your data is never permanently wiped. It is hidden from the active frontend and reporting engines but remains in the database with a deletion timestamp. This allows for forensic recovery and historical parity auditing.</li></ul></li></ul><hr><h2 id="⚠️-9-budget-management" tabindex="-1">⚠️ 9. Budget Management <a class="header-anchor" href="#⚠️-9-budget-management" aria-label="Permalink to &quot;⚠️ 9. Budget Management&quot;">​</a></h2><h3 id="creating-budgets" tabindex="-1">Creating Budgets <a class="header-anchor" href="#creating-budgets" aria-label="Permalink to &quot;Creating Budgets&quot;">​</a></h3><ol><li>Navigate to <strong>Budgets</strong> from the sidebar.</li><li>Click <strong>Add Budget</strong> and select a category.</li><li>Enter the monthly spending limit (₹).</li><li>Create an <strong>OVERALL</strong> budget for total family spending.</li></ol><h3 id="understanding-budget-alerts" tabindex="-1">Understanding Budget Alerts <a class="header-anchor" href="#understanding-budget-alerts" aria-label="Permalink to &quot;Understanding Budget Alerts&quot;">​</a></h3><p>WealthFam proactively monitors your spending and sends real-time alerts:</p><ul><li><strong>80% (Info)</strong> 🟡: &quot;You are approaching your limit. Moderate discretionary spending.&quot;</li><li><strong>100% (Warning)</strong> 🟠: &quot;Your limit has been reached.&quot;</li><li><strong>120% (Breach)</strong> 🔴: &quot;Significant overspending detected.&quot;</li></ul><p>These alerts are delivered via:</p><ul><li>WebSocket to connected web/mobile clients (instant).</li><li>Push notification on Android (via foreground service).</li></ul><h3 id="hierarchical-budgets" tabindex="-1">Hierarchical Budgets <a class="header-anchor" href="#hierarchical-budgets" aria-label="Permalink to &quot;Hierarchical Budgets&quot;">​</a></h3><p>Parent-level budgets <strong>automatically include</strong> spending from sub-categories. For example:</p><ul><li>Budget on <strong>&quot;Food&quot;</strong> ← includes all spending under <strong>&quot;Dining Out&quot;</strong>, <strong>&quot;Groceries&quot;</strong>, <strong>&quot;Delivery&quot;</strong>.</li><li>No manual aggregation needed; the system handles rollup automatically.</li></ul><h3 id="budget-history-forecast" tabindex="-1">Budget History &amp; Forecast <a class="header-anchor" href="#budget-history-forecast" aria-label="Permalink to &quot;Budget History &amp; Forecast&quot;">​</a></h3><ul><li><strong>Budget History Chart</strong>: View month-by-month spending trends for each category.</li><li><strong>Spending Forecast</strong>: See projected end-of-month spending based on your current daily velocity.</li></ul><hr><h2 id="🎯-10-investment-goals" tabindex="-1">🎯 10. Investment Goals <a class="header-anchor" href="#🎯-10-investment-goals" aria-label="Permalink to &quot;🎯 10. Investment Goals&quot;">​</a></h2><h3 id="creating-a-goal" tabindex="-1">Creating a Goal <a class="header-anchor" href="#creating-a-goal" aria-label="Permalink to &quot;Creating a Goal&quot;">​</a></h3><ol><li>Navigate to <strong>Investment Goals</strong> (Web) or <strong>Goals</strong> tab (Mobile).</li><li>Click <strong>Create Goal</strong> and enter: <ul><li><strong>Name</strong>: e.g., &quot;Retirement Fund&quot;, &quot;Dream Home&quot;.</li><li><strong>Target Amount</strong>: Your financial target (₹).</li><li><strong>Target Date</strong>: Optional deadline.</li><li><strong>Icon &amp; Color</strong>: Visual customization.</li><li><strong>Owner</strong>: Assign to a specific member or the whole family.</li></ul></li></ol><h3 id="linking-assets-to-goals" tabindex="-1">Linking Assets to Goals <a class="header-anchor" href="#linking-assets-to-goals" aria-label="Permalink to &quot;Linking Assets to Goals&quot;">​</a></h3><p>Goals support three asset types:</p><ul><li><strong>Mutual Fund Holdings</strong>: Link specific scheme holdings. The goal&#39;s progress tracks real-time NAV valuations.</li><li><strong>Bank Accounts</strong>: Link a bank account. The goal reflects the live account balance.</li><li><strong>Manual Assets</strong>: Add assets like EPF, Fixed Deposits, Gold with manual amounts and optional interest rates.</li></ul><h3 id="tracking-progress" tabindex="-1">Tracking Progress <a class="header-anchor" href="#tracking-progress" aria-label="Permalink to &quot;Tracking Progress&quot;">​</a></h3><ul><li>The goal card shows a <strong>progress bar</strong> (current value / target amount × 100).</li><li>When milestones are crossed, the system broadcasts a <strong>🎯 Goal Milestone!</strong> notification to all family members.</li></ul><hr><h2 id="🏛️-11-loans-debt-management" tabindex="-1">🏛️ 11. Loans &amp; Debt Management <a class="header-anchor" href="#🏛️-11-loans-debt-management" aria-label="Permalink to &quot;🏛️ 11. Loans &amp; Debt Management&quot;">​</a></h2><h3 id="adding-a-loan" tabindex="-1">Adding a Loan <a class="header-anchor" href="#adding-a-loan" aria-label="Permalink to &quot;Adding a Loan&quot;">​</a></h3><ol><li>Navigate to <strong>Loans</strong> from the sidebar.</li><li>Click <strong>Add Loan</strong> and fill in: <ul><li><strong>Loan Type</strong>: Home, Personal, Car, Education, Credit Card, Other.</li><li><strong>Principal Amount</strong>, <strong>Annual Interest Rate</strong>, <strong>Tenure (months)</strong>.</li><li><strong>EMI Amount</strong>, <strong>EMI Day</strong> (day of month).</li><li><strong>Source Bank Account</strong>: Where EMI is debited from.</li></ul></li><li>A dedicated Loan Account is automatically created.</li></ol><h3 id="amortization-installment-tracking" tabindex="-1">Amortization &amp; Installment Tracking <a class="header-anchor" href="#amortization-installment-tracking" aria-label="Permalink to &quot;Amortization &amp; Installment Tracking&quot;">​</a></h3><ol><li>Open any loan to view its dynamic <strong>Amortization Calendar</strong>.</li><li>WealthFam calculates your principal/interest split for every month of the tenure.</li><li><strong>Status Indicators</strong>: <ul><li>✅ <strong>PAID</strong>: A matching repayment transaction (EMI Date + Loan ID) was found in your ledger.</li><li>⚠️ <strong>OVERDUE</strong>: The due date has passed without a matching repayment detected.</li><li>🕒 <strong>PENDING</strong>: Future installments based on the original schedule.</li></ul></li></ol><h3 id="linking-emi-transactions" tabindex="-1">Linking EMI Transactions <a class="header-anchor" href="#linking-emi-transactions" aria-label="Permalink to &quot;Linking EMI Transactions&quot;">​</a></h3><p>When a bank transaction matches a loan EMI:</p><ol><li>Open the transaction (from Transactions or Triage).</li><li>In the edit view, find the <strong>Link to Loan</strong> dropdown.</li><li>Select the relevant loan.</li><li>The system updates the outstanding balance, reduces principal, and recalculates interest for the next term.</li></ol><h3 id="ai-loan-advisor" tabindex="-1">AI Loan Advisor <a class="header-anchor" href="#ai-loan-advisor" aria-label="Permalink to &quot;AI Loan Advisor&quot;">​</a></h3><p>On the Loan Details page:</p><ul><li>Click <strong>&quot;Get AI Advice&quot;</strong> to receive Gemini-powered analysis including: <ul><li>Interest rate comparison with market standards.</li><li>Prepayment strategies to save interest.</li><li>EMI burden assessment.</li><li>Specific actionable tips.</li></ul></li><li>On the Loans overview page, get <strong>portfolio-wide debt strategy</strong> (snowball vs. avalanche analysis).</li></ul><hr><h2 id="💼-12-expense-groups" tabindex="-1">💼 12. Expense Groups <a class="header-anchor" href="#💼-12-expense-groups" aria-label="Permalink to &quot;💼 12. Expense Groups&quot;">​</a></h2><h3 id="creating-an-expense-group" tabindex="-1">Creating an Expense Group <a class="header-anchor" href="#creating-an-expense-group" aria-label="Permalink to &quot;Creating an Expense Group&quot;">​</a></h3><ol><li>Navigate to <strong>Expense Groups</strong> from the sidebar.</li><li>Click <strong>Create Group</strong> and enter: <ul><li><strong>Name</strong>: e.g., &quot;Goa Trip&quot;, &quot;Wedding&quot;, &quot;Home Renovation&quot;.</li><li><strong>Budget</strong>: Total expected spending for this event.</li><li><strong>Date Range</strong>: Start and end dates (optional).</li><li><strong>Icon</strong>: Emoji for quick identification.</li></ul></li></ol><h3 id="assigning-transactions" tabindex="-1">Assigning Transactions <a class="header-anchor" href="#assigning-transactions" aria-label="Permalink to &quot;Assigning Transactions&quot;">​</a></h3><ul><li>From the <strong>Transaction Modal</strong>, select the Expense Group dropdown.</li><li>From the <strong>Expense Group Details</strong> page, click <strong>Manage Transactions</strong> to bulk-assign existing transactions.</li><li>On mobile, use the <strong>Manage Group Transactions</strong> screen to search and link transactions.</li></ul><h3 id="monitoring-spending" tabindex="-1">Monitoring Spending <a class="header-anchor" href="#monitoring-spending" aria-label="Permalink to &quot;Monitoring Spending&quot;">​</a></h3><p>Each group card shows:</p><ul><li><strong>Budget</strong> vs. <strong>Consumed</strong> with a progress bar.</li><li>Transaction list filtered to the group.</li><li>Date range and activity status.</li></ul><hr><h2 id="📂-13-document-vault" tabindex="-1">📂 13. Document Vault <a class="header-anchor" href="#📂-13-document-vault" aria-label="Permalink to &quot;📂 13. Document Vault&quot;">​</a></h2><h3 id="uploading-documents-web" tabindex="-1">Uploading Documents (Web) <a class="header-anchor" href="#uploading-documents-web" aria-label="Permalink to &quot;Uploading Documents (Web)&quot;">​</a></h3><ol><li>Navigate to <strong>Vault</strong> from the sidebar.</li><li>Click <strong>Upload</strong> and select a file.</li><li>Optionally: <ul><li>Assign a <strong>Document Type</strong> (Receipt, Invoice, Certificate, etc.).</li><li>Link to a <strong>Transaction</strong>.</li><li>Place in a <strong>Folder</strong>.</li></ul></li></ol><h3 id="uploading-documents-mobile" tabindex="-1">Uploading Documents (Mobile) <a class="header-anchor" href="#uploading-documents-mobile" aria-label="Permalink to &quot;Uploading Documents (Mobile)&quot;">​</a></h3><ol><li>Open the <strong>Vault</strong> tab on the mobile app.</li><li>Tap the <strong>Upload</strong> button and select a file from your device.</li><li>Thumbnails are auto-generated for images and PDFs.</li></ol><h3 id="folder-management" tabindex="-1">Folder Management <a class="header-anchor" href="#folder-management" aria-label="Permalink to &quot;Folder Management&quot;">​</a></h3><ul><li>Create folders to organize documents (e.g., &quot;Tax Documents&quot;, &quot;Insurance&quot;, &quot;Receipts&quot;).</li><li>Drag-and-drop or use <strong>Move</strong> to rearrange documents between folders.</li><li>Folders can be nested (parent-child hierarchy).</li></ul><h3 id="version-history" tabindex="-1">Version History <a class="header-anchor" href="#version-history" aria-label="Permalink to &quot;Version History&quot;">​</a></h3><ul><li>Re-uploading a file with the same name in the same folder automatically creates a <strong>new version</strong> (v1, v2, v3...).</li><li>Previous versions are preserved and accessible.</li></ul><h3 id="google-drive-cloud-sync" tabindex="-1">Google Drive Cloud Sync <a class="header-anchor" href="#google-drive-cloud-sync" aria-label="Permalink to &quot;Google Drive Cloud Sync&quot;">​</a></h3><ol><li>Go to <strong>Vault → Settings → Cloud Sync</strong>.</li><li>Enter your Google OAuth2 credentials (Client ID + Client Secret).</li><li>Complete the authorization flow.</li><li>Click <strong>Sync to Cloud</strong> — all vault documents are uploaded to a <code>WealthFam_Vault</code> folder in your Google Drive, preserving folder structure.</li></ol><h3 id="linking-documents-to-transactions" tabindex="-1">Linking Documents to Transactions <a class="header-anchor" href="#linking-documents-to-transactions" aria-label="Permalink to &quot;Linking Documents to Transactions&quot;">​</a></h3><ul><li>From the <strong>Transaction Modal</strong> → Documents section, attach documents.</li><li>From the <strong>Vault</strong>, click any document and use <strong>Link to Transaction</strong> to associate it.</li></ul><hr><h2 id="🧠-14-ai-configuration-insights" tabindex="-1">🧠 14. AI Configuration &amp; Insights <a class="header-anchor" href="#🧠-14-ai-configuration-insights" aria-label="Permalink to &quot;🧠 14. AI Configuration &amp; Insights&quot;">​</a></h2><h3 id="setting-up-ai" tabindex="-1">Setting Up AI <a class="header-anchor" href="#setting-up-ai" aria-label="Permalink to &quot;Setting Up AI&quot;">​</a></h3><ol><li>Go to <strong>Settings → AI Settings</strong>.</li><li>Enter your <strong>Gemini API Key</strong> (from Google AI Studio).</li><li>Select a <strong>Model</strong> (e.g., <code>gemini-1.5-flash</code>).</li><li>Toggle <strong>Enable AI</strong>.</li></ol><h3 id="what-ai-powers" tabindex="-1">What AI Powers <a class="header-anchor" href="#what-ai-powers" aria-label="Permalink to &quot;What AI Powers&quot;">​</a></h3><p>Once configured, AI enhances multiple features:</p><ul><li><strong>Dashboard Insights</strong>: 3 AI-generated observations on your spending patterns (refreshes every 24h).</li><li><strong>Loan Advice</strong>: Individual and portfolio-wide debt strategy analysis.</li><li><strong>Merchant Cleaning</strong>: Converts noisy bank descriptions into clean merchant names.</li><li><strong>Transaction Parsing</strong>: Smart extraction of transaction data from raw SMS/email content.</li><li><strong>Structured Insights</strong>: 5 detailed insights with type, title, icon, and actionable content.</li></ul><h3 id="managing-ai-cache" tabindex="-1">Managing AI Cache <a class="header-anchor" href="#managing-ai-cache" aria-label="Permalink to &quot;Managing AI Cache&quot;">​</a></h3><ul><li>AI insights are cached for <strong>24 hours</strong> to minimize API usage.</li><li>On the dashboard, a <strong>&quot;Cached&quot;</strong> chip appears if showing cached insights.</li><li>Click the <strong>Refresh</strong> button to force-regenerate fresh insights (uses API quota).</li></ul><hr><h2 id="🛡️-15-privacy-security" tabindex="-1">🛡️ 15. Privacy &amp; Security <a class="header-anchor" href="#🛡️-15-privacy-security" aria-label="Permalink to &quot;🛡️ 15. Privacy &amp; Security&quot;">​</a></h2><h3 id="masking-mode" tabindex="-1">Masking Mode <a class="header-anchor" href="#masking-mode" aria-label="Permalink to &quot;Masking Mode&quot;">​</a></h3><ul><li><strong>Use Case</strong>: Before reviewing financials in public or sharing your screen.</li><li><strong>How</strong>: Toggle the <strong>Eye Icon</strong> (masking mode) or use the <strong>&quot;Toggle Mask&quot;</strong> button on the Android foreground service notification.</li><li><strong>Effect</strong>: All absolute currency values are obfuscated (multiplied by a large factor). Percentage-based analytics and chart trends remain intact.</li></ul><h3 id="member-privacy" tabindex="-1">Member Privacy <a class="header-anchor" href="#member-privacy" aria-label="Permalink to &quot;Member Privacy&quot;">​</a></h3><ul><li><strong>Tenant Admins</strong> (OWNER role) can view aggregate family data and individual budgets.</li><li>Admins <strong>cannot</strong> see granular private transaction notes of other &quot;Adult&quot; members unless explicitly shared.</li><li><strong>Child</strong> role members only see their personal goals and limited dashboard data.</li></ul><h3 id="device-authorization" tabindex="-1">Device Authorization <a class="header-anchor" href="#device-authorization" aria-label="Permalink to &quot;Device Authorization&quot;">​</a></h3><ul><li>Every new mobile device generates a unique Hardware ID.</li><li>Navigate to <strong>Settings → Devices</strong> to see all registered devices.</li><li>Admin must approve each device before it can submit SMS transaction data.</li></ul><h3 id="session-security" tabindex="-1">Session Security <a class="header-anchor" href="#session-security" aria-label="Permalink to &quot;Session Security&quot;">​</a></h3><ul><li>JWT tokens are tracked via per-session JTI in the <code>UserToken</code> table.</li><li>Expired and revoked tokens are automatically pruned daily at <strong>03:00 UTC</strong>.</li><li>Multiple devices can maintain independent sessions.</li></ul><hr><h2 id="🔄-16-recurring-transactions" tabindex="-1">🔄 16. Recurring Transactions <a class="header-anchor" href="#🔄-16-recurring-transactions" aria-label="Permalink to &quot;🔄 16. Recurring Transactions&quot;">​</a></h2><h3 id="setting-up-recurring-bills" tabindex="-1">Setting Up Recurring Bills <a class="header-anchor" href="#setting-up-recurring-bills" aria-label="Permalink to &quot;Setting Up Recurring Bills&quot;">​</a></h3><ol><li>Navigate to <strong>Insights → Recurring</strong> tab.</li><li>Click <strong>Add Recurring</strong> and fill in: <ul><li><strong>Name</strong>: e.g., &quot;Netflix&quot;, &quot;Electricity Bill&quot;.</li><li><strong>Amount</strong> and <strong>Type</strong> (Debit/Credit).</li><li><strong>Frequency</strong>: Daily, Weekly, Bi-Weekly, Monthly, Quarterly, Yearly.</li><li><strong>Start Date</strong> and <strong>Account</strong>.</li><li><strong>Category</strong> (optional).</li></ul></li><li>The system automatically generates transactions on the scheduled dates.</li></ol><h3 id="how-auto-generation-works" tabindex="-1">How Auto-Generation Works <a class="header-anchor" href="#how-auto-generation-works" aria-label="Permalink to &quot;How Auto-Generation Works&quot;">​</a></h3><ul><li>The <code>daily_recurrence_check</code> runs every day at <strong>00:01 UTC</strong>.</li><li>It scans all <code>RecurringTransaction</code> records where <code>next_run_date &lt;= now</code> and <code>is_active == True</code>.</li><li>For each match, a transaction is created and <code>next_run_date</code> is advanced by the frequency.</li><li>Dashboard shows upcoming bills for the next 30 days.</li></ul><hr><h2 id="📱-17-mobile-specific-features" tabindex="-1">📱 17. Mobile-Specific Features <a class="header-anchor" href="#📱-17-mobile-specific-features" aria-label="Permalink to &quot;📱 17. Mobile-Specific Features&quot;">​</a></h2><h3 id="consolidated-dashboard-api" tabindex="-1">Consolidated Dashboard API <a class="header-anchor" href="#consolidated-dashboard-api" aria-label="Permalink to &quot;Consolidated Dashboard API&quot;">​</a></h3><p>The mobile app uses a single <code>get_consolidated_dashboard()</code> API call that returns:</p><ul><li>Summary metrics (today, yesterday, monthly totals).</li><li>Budget health.</li><li>Daily and monthly trends.</li><li>Category distribution.</li><li>Investment summary.</li><li>Recent transactions.</li><li>Triage count. This minimizes network round-trips for a smooth mobile experience.</li></ul><h3 id="spending-heatmap-mobile" tabindex="-1">Spending Heatmap (Mobile) <a class="header-anchor" href="#spending-heatmap-mobile" aria-label="Permalink to &quot;Spending Heatmap (Mobile)&quot;">​</a></h3><ul><li><code>spending_heatmap_widget.dart</code> — A GitHub-style calendar heatmap showing daily spending intensity.</li><li>Color gradients indicate relative spending levels across the month.</li></ul><h3 id="calendar-heatmap" tabindex="-1">Calendar Heatmap <a class="header-anchor" href="#calendar-heatmap" aria-label="Permalink to &quot;Calendar Heatmap&quot;">​</a></h3><ul><li><code>calendar_heatmap_widget.dart</code> — Visualize spending patterns across weeks and months with color-coded cells.</li></ul><h3 id="analytics-screen-mobile" tabindex="-1">Analytics Screen (Mobile) <a class="header-anchor" href="#analytics-screen-mobile" aria-label="Permalink to &quot;Analytics Screen (Mobile)&quot;">​</a></h3><ul><li><code>analytics_screen.dart</code> (52KB) — Full analytics with charts, category breakdowns, and trend analysis optimized for mobile interaction.</li></ul><hr><h2 id="🗂️-18-categories-rules" tabindex="-1">🗂️ 18. Categories &amp; Rules <a class="header-anchor" href="#🗂️-18-categories-rules" aria-label="Permalink to &quot;🗂️ 18. Categories &amp; Rules&quot;">​</a></h2><h3 id="managing-categories" tabindex="-1">Managing Categories <a class="header-anchor" href="#managing-categories" aria-label="Permalink to &quot;Managing Categories&quot;">​</a></h3><ol><li>Go to <strong>Categories</strong> from the sidebar (Web) or <strong>Categories Management</strong> (Mobile).</li><li>Create categories with: <ul><li><strong>Name</strong>: e.g., &quot;Food&quot;, &quot;Transport&quot;, &quot;Shopping&quot;.</li><li><strong>Icon</strong>: Emoji representation.</li><li><strong>Color</strong>: Hex color code.</li><li><strong>Type</strong>: Expense or Income.</li><li><strong>Parent</strong>: Optional — create sub-categories (e.g., &quot;Dining Out&quot; under &quot;Food&quot;).</li></ul></li></ol><h3 id="auto-categorization-rules" tabindex="-1">Auto-Categorization Rules <a class="header-anchor" href="#auto-categorization-rules" aria-label="Permalink to &quot;Auto-Categorization Rules&quot;">​</a></h3><ol><li>Go to <strong>Categories → Category Rules</strong>.</li><li>Create <strong>Category Rules</strong>: <ul><li><strong>Name</strong>: Rule identifier (e.g., &quot;Food Apps&quot;).</li><li><strong>Keywords</strong>: Matching strings (e.g., <code>[&quot;Zomato&quot;, &quot;Swiggy&quot;]</code>).</li><li><strong>Category</strong>: Target category to assign.</li><li><strong>Priority</strong>: Higher priority rules execute first.</li><li><strong>Is Transfer</strong>: Mark as transfer rule with destination account.</li><li><strong>Exclude from Reports</strong>: Auto-exclude matched transactions.</li></ul></li></ol><h3 id="reporting-unrecognized-alerts-help-improve-extraction" tabindex="-1">Reporting Unrecognized Alerts (Help Improve Extraction) <a class="header-anchor" href="#reporting-unrecognized-alerts-help-improve-extraction" aria-label="Permalink to &quot;Reporting Unrecognized Alerts (Help Improve Extraction)&quot;">​</a></h3><ol><li>Open <strong>Settings → Ingestions</strong> on Web or <strong>Ingestions</strong> (and <strong>Unrecognized Alerts</strong>) on Mobile.</li><li>Locate an SMS or Email labeled <strong>Could Not Extract</strong> / <strong>Unrecognized Alert</strong>.</li><li>Click <strong>Report Anonymized</strong> to inspect the scrubbed preview (which masks account digits, personal numbers, and amounts).</li><li>Review and confirm consent, then submit to help improve automatic bank alert coverage.</li></ol><hr><h2 id="🏷️-19-merchant-alias-management" tabindex="-1">🏷️ 19. Merchant Alias Management <a class="header-anchor" href="#🏷️-19-merchant-alias-management" aria-label="Permalink to &quot;🏷️ 19. Merchant Alias Management&quot;">​</a></h2><h3 id="creating-an-alias" tabindex="-1">Creating an Alias <a class="header-anchor" href="#creating-an-alias" aria-label="Permalink to &quot;Creating an Alias&quot;">​</a></h3><ol><li>Navigate to <strong>Categories → Category Rules → Merchant Aliases</strong> (or trigger rename from <strong>Transactions</strong>).</li><li>Click <strong>New Alias</strong>.</li><li>Enter the <strong>Raw Text Pattern</strong> (the noisy text from the bank, e.g., <code>AMZN MKTP</code>) and the <strong>Clean Merchant Name</strong> (e.g., <code>Amazon</code>).</li></ol><h3 id="retroactive-updates" tabindex="-1">Retroactive Updates <a class="header-anchor" href="#retroactive-updates" aria-label="Permalink to &quot;Retroactive Updates&quot;">​</a></h3><ul><li>When saving an alias, check <strong>&quot;Apply to existing transactions?&quot;</strong>.</li><li>WealthFam previews how many ledger and triage transactions match before scanning history and renaming them automatically across SMS, Email, PDF Statements, and CSV imports.</li></ul><hr><h2 id="📋-20-ingestion-activity-ignore-control" tabindex="-1">📋 20. Ingestion Activity &amp; Ignore Control <a class="header-anchor" href="#📋-20-ingestion-activity-ignore-control" aria-label="Permalink to &quot;📋 20. Ingestion Activity &amp; Ignore Control&quot;">​</a></h2><h3 id="monitoring-sms-email-ingestions" tabindex="-1">Monitoring SMS &amp; Email Ingestions <a class="header-anchor" href="#monitoring-sms-email-ingestions" aria-label="Permalink to &quot;Monitoring SMS &amp; Email Ingestions&quot;">​</a></h3><ol><li>Go to <strong>Settings → Ingestions</strong> (Web) or open <strong>Ingestions → Ingestion Activity</strong> (Mobile).</li><li>Filter by <strong>Date Range</strong> (defaulting to <strong>Today</strong>, with presets for Yesterday, Last 7 Days, Last 30 Days, This Month, All Time, or custom dates), <strong>Person</strong>, <strong>Source</strong> (<code>All Sources</code>, <code>SMS</code>, <code>Email</code>), <strong>Device / Mailbox</strong>, <strong>Account</strong>, <strong>Outcome</strong>, or full-text <strong>Search</strong>.</li><li>Click <strong>View Content</strong> on any row to expand the full SMS or Email body and see the plain-language outcome (<em>Added to Ledger</em>, <em>Needs Review</em>, <em>Account Not Linked</em>, <em>Duplicate Skipped</em>, <em>Ignored by Rule</em>, <em>Non-Financial / OTP</em>, or <em>Unrecognized Alert</em>) alongside direct action links.</li></ol><h3 id="ignoring-senders-re-allowing-later" tabindex="-1">Ignoring Senders &amp; Re-Allowing Later <a class="header-anchor" href="#ignoring-senders-re-allowing-later" aria-label="Permalink to &quot;Ignoring Senders &amp; Re-Allowing Later&quot;">​</a></h3><ol><li>On any SMS or Email row in <strong>Settings → Ingestions</strong>, click <strong>Ignore</strong> (or <strong>Ignore in Future</strong> on Mobile) to match by sender, subject phrase, or body/filename keyword and channel (<code>SMS</code>, <code>EMAIL</code>, <code>STATEMENT</code> / <em>Email Statements (PDF)</em>, or <code>ALL</code>).</li><li>Future matching messages (or email <code>.pdf</code> statement attachments for <code>STATEMENT</code>) are discarded immediately before processing while remaining visible under the <strong>Ignored by Rule</strong> outcome for SMS/Email.</li><li>Click <strong>Allow</strong> directly on an ignored row or inside the <strong>Ignored Rules</strong> modal to stop blocking that sender/keyword at any time. Statement PDF ignore rules can also be managed directly from <strong>Banking → Statements → Ignored Rules</strong> on Web or by choosing <strong>Email Statements (PDF)</strong> in Mobile <strong>Ingestions</strong>.</li></ol><hr><h2 id="🏦-21-auto-account-discovery" tabindex="-1">🏦 21. Auto-Account Discovery <a class="header-anchor" href="#🏦-21-auto-account-discovery" aria-label="Permalink to &quot;🏦 21. Auto-Account Discovery&quot;">​</a></h2><h3 id="how-to-use-auto-discovery" tabindex="-1">How to use Auto-Discovery <a class="header-anchor" href="#how-to-use-auto-discovery" aria-label="Permalink to &quot;How to use Auto-Discovery&quot;">​</a></h3><ol><li>When a transaction arrives for an unknown account, WealthFam creates a &quot;Detected&quot; account (e.g., <code>Detected: SMS (XX1234)</code>).</li><li>Navigate to <strong>Settings → Accounts</strong>.</li><li>Find the account marked with the <strong>&quot;Unverified&quot;</strong> badge.</li><li>Click <strong>Edit</strong>, provide a proper name (e.g., &quot;HDFC Savings&quot;), and click <strong>Verify</strong>.</li><li>All future transactions for this mask will now map to your verified account.</li></ol><hr><h2 id="🛠️-22-deep-how-to-advanced-workflows" tabindex="-1">🛠️ 22. Deep How-To: Advanced Workflows <a class="header-anchor" href="#🛠️-22-deep-how-to-advanced-workflows" aria-label="Permalink to &quot;🛠️ 22. Deep How-To: Advanced Workflows&quot;">​</a></h2><h3 id="how-to-handle-split-transactions" tabindex="-1">How to Handle Split Transactions <a class="header-anchor" href="#how-to-handle-split-transactions" aria-label="Permalink to &quot;How to Handle Split Transactions&quot;">​</a></h3><p>Often, a single bank transaction represents multiple categories (e.g., a Grocery store bill that includes Food and Home Supplies).</p><ol><li>Open the transaction in the <strong>Transaction Modal</strong>.</li><li>Click <strong>Split Transaction</strong>.</li><li>Add rows for each sub-category and assign amounts.</li><li>The sum must match the total transaction amount.</li><li><strong>Result</strong>: Your parent ledger remains accurate, but reports will show the split breakdown.</li></ol><h3 id="how-to-master-categorization-rules" tabindex="-1">How to Master Categorization Rules <a class="header-anchor" href="#how-to-master-categorization-rules" aria-label="Permalink to &quot;How to Master Categorization Rules&quot;">​</a></h3><p>To automate your financial life, use prioritized keywords.</p><ol><li>Go to <strong>Categories → Category Rules</strong>.</li><li><strong>Standard Rule</strong>: <code>keywords: [&quot;Amazon&quot;, &quot;Flipkart&quot;]</code> → Category: <code>Shopping</code>.</li><li><strong>High-Priority Exception</strong>: <code>keywords: [&quot;Amazon Cloud&quot;, &quot;AWS&quot;]</code> → Category: <code>Education/Work</code> (Set Priority to 10).</li><li><strong>Order Matters</strong>: The system evaluates rules in descending order of priority. Always set specialized rules higher than generic ones.</li></ol><h3 id="how-to-perform-a-portfolio-migration" tabindex="-1">How to Perform a &quot;Portfolio Migration&quot; <a class="header-anchor" href="#how-to-perform-a-portfolio-migration" aria-label="Permalink to &quot;How to Perform a &quot;Portfolio Migration&quot;&quot;">​</a></h3><p>If you are moving from another app to WealthFam:</p><ol><li>Export your data as <strong>CSV</strong>.</li><li>Go to <strong>WealthHub → Settings → Tools → Importer</strong>.</li><li>Map your columns to the WealthFam schema.</li><li>Use the <strong>Preview Mode</strong> to catch mapping errors before final ingestion.</li></ol><hr><h2 id="⚡-23-attention-hub-action-required-center" tabindex="-1">⚡ 23. Attention Hub &amp; Action Required Center <a class="header-anchor" href="#⚡-23-attention-hub-action-required-center" aria-label="Permalink to &quot;⚡ 23. Attention Hub &amp; Action Required Center&quot;">​</a></h2><p>The <strong>Attention Hub</strong> gives you a single place to review all pending decisions, deadlines, and anomalies across your household finances.</p><h3 id="web-dashboard-1" tabindex="-1">Web Dashboard <a class="header-anchor" href="#web-dashboard-1" aria-label="Permalink to &quot;Web Dashboard&quot;">​</a></h3><ol><li>Look at the top navigation bar for the Bell icon. When actions are pending, it displays an amber badge count: <code>🔔 {N}</code>. <ul><li>If pulsing, items require your review.</li><li>If it reads <code>Caught up</code>, all statements, debts, and transactions are reconciled.</li></ul></li><li>Click the pill to open the <strong>Action Required</strong> drawer.</li><li>Click any action item to jump directly to its screen (e.g. Card Due opens the specific Credit Card, Budget Breach opens the over-limit Category, etc.).</li><li>Switch to the <strong>Notifications</strong> tab to view real-time WebSocket alerts and milestones.</li></ol><h3 id="mobile-app-android" tabindex="-1">Mobile App (Android) <a class="header-anchor" href="#mobile-app-android" aria-label="Permalink to &quot;Mobile App (Android)&quot;">​</a></h3><ol><li>On the main <strong>Dashboard</strong>, a dedicated <strong>ACTION</strong> row appears directly below your Monthly Overview hero card whenever actions are pending.</li><li>The row displays quick-action chips with live counters: <ul><li><strong>Review Transactions</strong>: Opens unverified SMS/Email transactions for 1-tap categorization.</li><li><strong>Statements</strong>: Shows parsed statements requiring review or password unlock.</li><li><strong>Transfers</strong>: Jump to Transfers Hub to confirm detected account transfers.</li><li><strong>Cards Due</strong>: Highlights credit cards with bills due in $\\le 5$ days or overdue.</li><li><strong>Over Budget</strong>: Direct link to categories exceeding your monthly spending cap.</li><li><strong>EMIs Due</strong>: Alerts when loan installment dates are approaching.</li><li><strong>Recurring Found</strong>: Review automated recurring subscription detections.</li><li><strong>Low Balance</strong>: Warns if savings accounts dip below minimum balance thresholds.</li><li><strong>Update CAS</strong>: Reminds you when mutual fund valuations are $&gt; 30$ days old.</li></ul></li><li>When all items are attended, the row automatically collapses to zero height.</li></ol><h3 id="marking-statements-as-attended" tabindex="-1">Marking Statements as Attended <a class="header-anchor" href="#marking-statements-as-attended" aria-label="Permalink to &quot;Marking Statements as Attended&quot;">​</a></h3><ol><li>Go to <strong>Statements</strong> (Web or Mobile).</li><li>Unattended parsed statements display an amber <code>Needs Review</code> badge.</li><li>After reviewing transactions, tap <strong>&quot;Mark Attended&quot;</strong>. <ul><li>If all transactions are reconciled, it marks attended immediately.</li><li>If unreconciled transactions remain, a warning dialog prompts for your confirmation.</li></ul></li><li>You can tap <strong>&quot;Reopen&quot;</strong> at any time to return the statement to the review queue.</li><li>Reprocessing a statement via <code>POST /statements/{id}/reprocess</code> automatically resets it to <code>is_attended = False</code>.</li></ol><hr><div align="center"> *Engineering Financial Freedom* *Made with ❤️ by WGLabz* </div>',228)])])}const m=t(i,[["render",r]]);export{h as __pageData,m as default};
